{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil rides the coach and steps off at Pittsburgh.",
  "Rita said in the lobby: I don't speak to the crew. I push the door and go.",
  "Larry said in the lobby: To the crew, over my shoulder, not turning around: \"Taking the charge. Alma's got a girl in Pittsburgh and the place is going dark. You guys shoot the ballroom tonight, I'll be back.\"",
  "You are now at Pittsburgh.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hi, is the van driver still confirming for 8 AM tomorrow? I'm at the terminal now."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "afternoon": "Phil plays the last eight bars until he can get through them.",
   "evening": "Phil sits on the empty depot bench.",
   "what_you_said": "",
   "your_last_intention": "Test the variable by being in the room instead of above it. The piano was shape. The loop was shape. This is weight. I want to know if the Tuesday in my chest loosens by one degree when I am not the voice, not the man behind the glass, not the one who plays the bars until they go through. I want to know if the evening is different in the body of a man in a folding chair behind the lighting rig, watching a crowd that does not know he is there. I do not need it to be different. I need to know whether it is.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "what_you_did": "Phil rides the coach and steps off at Pittsburgh.",
   "what_you_said": "I turn to Rita and Larry. I say: I'm heading to the station. Coach to Pittsburgh. I'll be back by the party, or I won't be. Either way. I pick up my bag. I walk out the door. I don't wait for an answer. I don't need one.",
   "your_intention": "Be in Pittsburgh. Be at the terminal. Make the call. Confirm the van. Be there when the couch needs moving. Do the thing. Not test the shape. Do the thing."
  },
  "Phil rides the coach and steps off at Pittsburgh.",
  "Rita said in the lobby: I don't speak to the crew. I push the door and go.",
  "Larry said in the lobby: To the crew, over my shoulder, not turning around: \"Taking the charge. Alma's got a girl in Pittsburgh and the place is going dark. You guys shoot the ballroom tonight, I'll be back.\"",
  "You are now at Pittsburgh."
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "call_sister": "Use the Pittsburgh payphone to call your sister.",
  "sleep_at_terminal": "Sleep on the terminal bench.",
  "wait_for_morning": "Sit up through the evening and wait for morning."
 }
}
